import sys

data = sys.stdin.read().split()
n = int(data[0])
val = [int(data[1 + i]) for i in range(n)]
edges = []
p = 1 + n
for _ in range(n - 1):
    edges.append((int(data[p]), int(data[p + 1])))
    p += 2
total = sum(val)
best = None
for k in range(n - 1):
    adj = [[] for _ in range(n)]
    for idx, (u, v) in enumerate(edges):
        if idx != k:
            adj[u].append(v)
            adj[v].append(u)
    seen = {0}
    stack = [0]
    while stack:
        u = stack.pop()
        for v in adj[u]:
            if v not in seen:
                seen.add(v)
                stack.append(v)
    s1 = sum(val[u] for u in seen)
    d = abs(s1 - (total - s1))
    if best is None or d < best:
        best = d
print(best)

